// src/cli/renderers/cursor-limits-core.js
// cursor-limits.json's text: the version of the CLI that judged (it holds
// the constants), the versions the data was recorded with, every constant the
// cursor section judged with (value and meaning), the realised sampling
// interval across the cohort and the verdicts over the cohort, so a report
// regenerated by a later CLI shows which constants adjudicated it. No fs
// access: report-core.js sinks it.

import { CURSOR_LIMITS } from '../analyzers/cursor.js';
import { VERSION } from '../../shared/constants.js';

function median(values) {
  if (!values.length) return null;
  const s = values.slice().sort((a, b) => a - b);
  const mid = s.length >> 1;
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

// recordedWith: the library versions the data names, in version order and
// joined by ", " (null when it names none).
// limits: the limits object the results were judged with (shaped like
// CURSOR_LIMITS, the default); the file writes it as given.
export function buildCursorLimitsJson(recordedWith, results, limits = CURSOR_LIMITS) {
  const intervals = results.map(r => r.cursor && r.cursor.sampleIntervalMs).filter(v => typeof v === 'number');
  // Sessions with device facts, as the run line counts them.
  const withDeviceFacts = results.filter(r => r.checksRecorded >= 1).length;
  // The verdicts over the cohort, as the run line counts them.
  const verdicts = { highlySuspicious: 0, suspicious: 0, clean: 0, notAssessed: 0 };
  for (const r of results) verdicts[['notAssessed', 'clean', 'suspicious', 'highlySuspicious'][r.level + 1]]++;
  return JSON.stringify({
    cliVersion: VERSION,
    recordedWith,
    limits,
    sampleIntervalMs: { core: { median: median(intervals), n: intervals.length } },
    sessions: { total: results.length, withDeviceFacts, verdicts }
  }, null, 2) + '\n';
}
